package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;

/**
 * Rejects a create request whose telephone is already used by another owner, so a
 * duplicate is a 409. Runs after {@link ValidateOwnerFields} has normalized the telephone
 * to E.164 form, comparing against every existing owner's telephone in E.164 form so that
 * national and international spellings of the same number collide.
 */
public class EnsureUniqueTelephone {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateTelephoneException {
        String telephone = TelephoneE164.normalize(request.getTelephone());
        for (Owner existing : ownerRepository.findAll()) {
            if (telephone != null && telephone.equals(TelephoneE164.normalize(existing.getTelephone()))) {
                throw new DuplicateTelephoneException(telephone);
            }
        }
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;

import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.MissingFieldsException;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Rejects a create request that is missing or blank in any required owner field, so an
 * incomplete body is a 400 whose {@code errors} array names each offending field. Also
 * normalizes the telephone to E.164 form (see {@link TelephoneE164}), republishing the
 * normalized value so it is stored and returned as {@code telephone}; a telephone that
 * cannot form a valid E.164 number is a 400 too.
 * The optional {@code email} is validated only when present: a syntactically invalid
 * address is a 400, otherwise it is normalized to lower-case and republished so it is
 * stored and returned lower-cased.
 * The {@code address} is normalized (see {@link AddressNormalizer}) and republished so it
 * is stored and returned in canonical form; an address that is blank after normalization
 * is a required-field 400.
 * Runs first and republishes the body as a variable for {@link BuildOwner}.
 */
public class ValidateOwnerFields {

    /** Syntactic email check: one '@', non-empty local part, and a dotted domain. */
    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");

    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
            throws MissingFieldsException {
        List<String> errors = new ArrayList<>();
        if (isBlank(request.getFirstName())) {
            errors.add("firstName");
        }
        if (isBlank(request.getLastName())) {
            errors.add("lastName");
        }
        String address = AddressNormalizer.normalize(request.getAddress());
        if (address.isEmpty()) {
            errors.add("address");
        }
        else {
            request.setAddress(address);
        }
        if (isBlank(request.getCity())) {
            errors.add("city");
        }
        String telephone = TelephoneE164.normalize(request.getTelephone());
        if (telephone == null) {
            errors.add("telephone");
        }
        else {
            request.setTelephone(telephone);
        }
        String email = request.getEmail();
        if (email != null && !email.isBlank()) {
            String normalized = email.trim().toLowerCase();
            if (!EMAIL.matcher(normalized).matches()) {
                errors.add("email");
            }
            else {
                request.setEmail(normalized);
            }
        }
        if (!errors.isEmpty()) {
            throw new MissingFieldsException(errors);
        }
        validated.set(request);
    }

    private static boolean isBlank(String value) {
        return value == null || value.isBlank();
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;

/**
 * Rejects a create request whose lastName and address together already identify another
 * owner, so a household duplicate is a 409. lastName is compared case-insensitively with
 * collapsed whitespace, so " Smith " and "smith" collide. address is compared in its
 * normalized form (see {@link AddressNormalizer}), so "12 Main St" and "12  main  street"
 * collide. A request may opt out of this check by setting {@code sharesHousehold} true,
 * allowing several owners at one household.
 */
public class EnsureUniqueHousehold {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateHouseholdException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String lastName = normalize(request.getLastName());
        String address = AddressNormalizer.normalize(request.getAddress());
        for (Owner existing : ownerRepository.findAll()) {
            if (lastName.equals(normalize(existing.getLastName()))
                    && address.equals(AddressNormalizer.normalize(existing.getAddress()))) {
                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
            }
        }
    }

    /** Case-insensitive with collapsed whitespace: trim, fold internal whitespace runs to a
     *  single space, and lower-case. */
    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}

